int solve(int n, int p) {
    static std::map<std::pair<int,int>, int> memo;
    auto key = std::make_pair(n, p);
    auto it = memo.find(key);
    if (it != memo.end()) return it->second;

    bool res;
    if (n == 0) {
        res = true;
    } else {
        long long pow3 = 1;
        for (int i = 0; i < p; ++i) {
            pow3 *= 3;
            if (pow3 > n) break;
        }
        if (pow3 > n) {
            res = false;
        } else {
            int take = solve(n - static_cast<int>(pow3), p + 1);
            int skip = solve(n, p + 1);
            res = take || skip;
        }
    }
    memo[key] = res;
    return memo[key];
}

