bool dfs(int a[], int j, int k, int n, int vis[], int t, int c)
{
  if (c > t) return false;
  if (j == k) return true;
  if (c == t) return dfs(a, j + 1, k, n, vis, t, 0);

  unsigned long long mask = 0;
  for (int i = 0; i < n; ++i) {
    if (vis[i]) mask |= 1ULL << i;
  }

  static std::map<std::tuple<int,int,unsigned long long>, char> memo;
  auto key = std::make_tuple(j, c, mask);
  auto it = memo.find(key);
  if (it != memo.end()) return it->second != 0;

  for (int l = 0; l < n; ++l) {
    if (!vis[l]) {
      vis[l] = 1;
      if (dfs(a, j, k, n, vis, t, c + a[l])) {
        memo[key] = 1;
        return true;
      }
      vis[l] = 0;
    }
  }
  memo[key] = 0;
  return false;
}

