using namespace std;
int countSeq(int n,int diff) {
    if (abs(diff) > n) return 0;
    if (n <= 0) return 0;
    int offset = n;
    vector<vector<int>> dp(n + 1, vector<int>(2 * n + 1, 0));
    dp[1][offset] = 2;
    if (2 * n + 1 > offset + 1) dp[1][offset + 1] = 1;
    if (offset - 1 >= 0) dp[1][offset - 1] = 1;
    for (int i = 2; i <= n; ++i) {
        for (int d = -i; d <= i; ++d) {
            int idx = d + offset;
            int up   = dp[i - 1][d + 1 + offset];
            int mid  = dp[i - 1][d + offset];
            int down = dp[i - 1][d - 1 + offset];
            dp[i][idx] = up + 2 * mid + down;
        }
    }
    return dp[n][diff + offset];
}

