int min_op(int cur,int M) {
    static vector<int> memo;
    static int memoM = -1;
    if (M != memoM) {
        memoM = M;
        memo.assign(M + 1, -2);
    }
    if (cur > M) return INF;
    if (cur == M) return 0;
    if (cur >= 0 && cur <= M && memo[cur] != -2) return memo[cur];
    int op = INF;
    for (int i = 2; i * i <= cur; ++i) {
        if (cur % i == 0) {
            if (i % 2 == 0) {
                op = min(op, 1 + min_op(cur + i, M));
            }
            int d = cur / i;
            if (d != i && d % 2 == 0) {
                op = min(op, 1 + min_op(cur + d, M));
            }
        }
    }
    if (cur >= 0 && cur <= M) memo[cur] = op;
    return op;
}
