using namespace std;
bool isScramble(string S1, string S2) {
    if (S1.size() != S2.size()) return false;
    int n = (int)S1.size();
    if (n == 0) return true;

    // memo[i][j][len] = -1 unknown, 0 false, 1 true
    vector<vector<vector<char>>> memo(n, vector<vector<char>>(n, vector<char>(n + 1, -1)));

    auto charFreqEqual = [&](int i1, int j1, int len) -> bool {
        int cnt[256] = {0};
        for (int k = 0; k < len; ++k) {
            ++cnt[(unsigned char)S1[i1 + k]];
            --cnt[(unsigned char)S2[j1 + k]];
        }
        for (int c = 0; c < 256; ++c) if (cnt[c] != 0) return false;
        return true;
    };

    function<char(int,int,int)> dfs = [&](int i, int j, int len) -> char {
        char &res = memo[i][j][len];
        if (res != -1) return res;
        if (S1.compare(i, len, S2, j, len) == 0) return res = 1;
        if (!charFreqEqual(i, j, len)) return res = 0;
        for (int k = 1; k < len; ++k) {
            if (dfs(i, j, k) == 1 && dfs(i + k, j + k, len - k) == 1) return res = 1;
            if (dfs(i, j + len - k, k) == 1 && dfs(i + k, j, len - k) == 1) return res = 1;
        }
        return res = 0;
    };

    return dfs(0, 0, n) == 1;
}

