void heapify(int A[], int n, int i)
{
  std::stack<int> st;
  st.push(i);
  while (!st.empty()) {
    int idx = st.top();
    st.pop();

    int large = idx;
    int left = 2 * idx + 1;
    int right = 2 * idx + 2;

    if (left < n && A[large] < A[left])
      large = left;
    if (right < n && A[large] < A[right])
      large = right;

    if (large == idx)
      continue;

    std::swap(A[large], A[idx]);
    // recursive call heapify(A, n, large) is simulated by pushing large
    st.push(large);
  }
}

