#include <stack>
#include <utility>

int nCr(int n, int r) {
    if (n < r) return 0;
    if (r == 0) return 1;

    // Explicit stack replaces the implicit call stack
    std::stack<std::pair<int,int>> st;
    int cur_n = n;
    int cur_r = r;
    // Build the call chain that recursion would have created
    while (cur_r > 0 && cur_n >= cur_r) {
        st.push({cur_n, cur_r});
        cur_n--;
        cur_r--;
    }
    long long res = (cur_n < cur_r) ? 0 : 1; // base case
    while (!st.empty()) {
        auto [cn, cr] = st.top();
        st.pop();
        // unwind in the same order the recursive calls would return
        res = cn * res / cr;
    }
    return static_cast<int>(res);
}

