int power_rec(int base, int exp, int mod) {
    struct Frame {
        int base;
        int exp;
        int mod;
        bool visited;
    };
    std::stack<Frame> st;
    std::stack<int> results;
    st.push({base, exp, mod, false});

    while (!st.empty()) {
        Frame f = st.top();
        st.pop();

        if (f.exp == 0) {
            results.push(1);
            continue;
        }

        if (!f.visited) {
            st.push({f.base, f.exp, f.mod, true});
            int childBase = (f.base * f.base) % f.mod;
            int childExp = f.exp >> 1;
            st.push({childBase, childExp, f.mod, false});
        } else {
            int childRes = results.top();
            results.pop();
            int curRes = (f.exp & 1) ? (childRes * f.base) % f.mod : childRes;
            results.push(curRes);
        }
    }
    return results.top();
}

