void findmax(string str, string &ans, int k, int n, int i)
{
    struct Frame {
        string s;
        int k;
        int i;
    };

    std::stack<Frame> st;
    st.push({str, k, i});

    while (!st.empty()) {
        Frame cur = st.top();
        st.pop();

        string s = std::move(cur.s);
        int curk = cur.k;
        int curi = cur.i;

        if (curk <= 0) continue;

        char maxs = s[curi];
        for (int j = curi + 1; j < n; ++j) {
            maxs = std::max(maxs, s[j]);
        }

        if (maxs != s[curi]) --curk;

        // push children in reverse order to keep the same DFS order as recursion
        for (int j = n - 1; j >= curi; --j) {
            if (s[j] == maxs) {
                string ns = s;
                std::swap(ns[curi], ns[j]);
                if (ans < ns) ans = ns;
                if (curk > 0) {
                    st.push({std::move(ns), curk, curi + 1});
                }
            }
        }
    }
}

