int sumOfDigitsFrom1ToN(int n) {
    std::stack<int> st;
    st.push(n);
    long long total = 0;
    while (!st.empty()) {
        int cur = st.top();
        st.pop();
        if (cur < 10) {
            total += 1LL * cur * (cur + 1) / 2;
            continue;
        }
        int d = (int)log10(cur);
        int *a = new int[d + 1];
        a[0] = 0; a[1] = 45;
        for (int i = 2; i <= d; ++i) a[i] = a[i - 1] * 10 + 45 * (int)ceil(pow(10, i - 1));
        int p = (int)ceil(pow(10, d));
        int msd = cur / p;
        long long contrib = 1LL * msd * a[d] + 1LL * (msd * (msd - 1) / 2) * p + 1LL * msd * (1 + cur % p);
        total += contrib;
        st.push(cur % p);
        delete[] a;
    }
    return (int)total;
}

