    struct Frame {
        int index;
        size_t next_i;
        vector<int> cur;
    };
    std::stack<Frame> st;
    st.push({index, 0, cur});

    while(!st.empty()){
        Frame &fr = st.top();

        if(fr.index == static_cast<int>(nums.size())){
            bool allZero = true;
            for(int e : fr.cur){
                if(e != 0){ allZero = false; break; }
            }
            if(allZero) return true;
            st.pop();
            continue;
        }

        if(fr.next_i >= fr.cur.size()){
            st.pop();
            continue;
