        size_t i = fr.next_i++;
        if(fr.cur[i] >= nums[fr.index]){
            vector<int> newCur = fr.cur;
            newCur[i] -= nums[fr.index];
            st.push({fr.index + 1, 0, std::move(newCur)});
        }
    }
    return false;
}

