int minDistance(string word1, string word2) {
    // Replace the recursive swap with explicit normalisation - no call stack needed
    if (word1.size() < word2.size())
        std::swap(word1, word2);

    const size_t m = word1.size();
    const size_t n = word2.size();

    vector<size_t> f(n + 1);
    for (size_t i = 0; i <= n; ++i) f[i] = i;

    for (size_t i = 1; i <= m; ++i) {
        size_t upper_left = f[0];
        f[0] = i;
        for (size_t j = 1; j <= n; ++j) {
            size_t upper = f[j];
            if (word1[i - 1] == word2[j - 1]) {
                f[j] = upper_left;
            } else {
                f[j] = 1 + std::min({upper_left, f[j - 1], upper});
            }
            upper_left = upper;
        }
    }

    return static_cast<int>(f[n]);
}

