            parent.best = std::min(parent.best, 1 + ret);
            continue;
        }
        if(f.nextNeg >= f.neg.size()){
            int ret = f.best;
            st.pop();
            if(st.empty()) return ret;
            Frame &parent = st.top();
            parent.best = std::min(parent.best, ret);
            continue;
        }
        size_t eIdx = f.nextNeg++;
        if(f.neg[eIdx] == 0) continue;
        int t = std::min(f.pos[f.index], f.neg[eIdx]);
        vector<int> childPos = f.pos;
        vector<int> childNeg = f.neg;
        childPos[f.index] -= t;
        childNeg[eIdx] -= t;
        int childIdx = f.index + (childPos[f.index] == 0 ? 1 : 0);
        st.push({std::move(childPos), std::move(childNeg), childIdx, 0, INT_MAX});
    }
    return INT_MAX;
}

