void get_option_states(const vector<int>& options, int index, int k, int state, vector<int>& res){
    struct Frame {
        int index;
        int k;
        int state;
    };
    std::stack<Frame> st;
    st.push({index, k, state});
    while(!st.empty()){
        Frame cur = st.top();
        st.pop();
        if(cur.k == 0){
            res.push_back(cur.state);
            continue;
        }
        if(cur.index >= static_cast<int>(options.size())) continue;
        // push children in reverse order so the smallest i is processed first
        // this preserves the original recursive order
        for(int i = static_cast<int>(options.size()) - 1; i >= cur.index; --i){
            int newState = cur.state | (1 << options[i]);
            st.push({i + 1, cur.k - 1, newState});
        }
    }
}

