int getHermiteNumber(int n) {
    if (n < 0) return 0; // guard, original would recurse forever
    struct Frame { int n; bool done; };
    std::stack<Frame> st;
    std::stack<long long> vals;
    st.push({n, false});
    while (!st.empty()) {
        Frame f = st.top();
        st.pop();
        if (f.n == 0) {
            vals.push(1);
            continue;
        }
        if (f.n == 1) {
            vals.push(0);
            continue;
        }
        if (!f.done) {
            // simulate the recursive call getHermiteNumber(n-2)
            st.push({f.n, true});
            st.push({f.n - 2, false});
        } else {
            long long child = vals.top(); vals.pop();
            long long cur = -2LL * (f.n - 1) * child;
            vals.push(cur);
        }
    }
    return static_cast<int>(vals.top());
}

