int binExpo(int a, int b) {
    // explicit call stack instead of recursion
    std::stack<int> st;
    st.push(b);
    std::vector<int> order;
    while (!st.empty()) {
        int cur = st.top();
        st.pop();
        order.push_back(cur);
        if (cur > 0) {
            st.push(cur / 2); // the recursive call binExpo(a, b/2)
        }
    }
    int res = 1; // value for b == 0
    for (int i = static_cast<int>(order.size()) - 2; i >= 0; --i) {
        int curB = order[i];
        if (curB & 1) {
            res = res * res * a;
        } else {
            res = res * res;
        }
    }
    return res;
}

