int pow(int b, int p) {
    struct Frame {
        int b;
        int p;
        int stage;      // 0 = entry, 1 = after child
        int childRes;
    };

    std::stack<Frame> st;
    st.push({b, p, 0, 0});
    int result = 1;

    while (!st.empty()) {
        Frame &f = st.top();
        if (f.stage == 0) {
            if (f.p == 0) {
                f.childRes = 1;
                st.pop();
                if (!st.empty()) {
                    Frame &parent = st.top();
                    parent.childRes = f.childRes;
                }
                continue;
            }
            f.stage = 1;
            st.push({f.b, f.p / 2, 0, 0});
        } else {
            int sq = f.childRes;
            sq = sq * sq;
            if (f.p % 2 == 1) sq = sq * f.b;
            f.childRes = sq;
            if (st.size() == 1) {
                result = sq;
                break;
            }
            st.pop();
            Frame &parent = st.top();
            parent.childRes = f.childRes;
        }
    }
    return result;
}

