string commonPrefix(string arr[],int low,int high) {
    if(low>high) return "";
    if(low==high) return arr[low];

    struct Frame { int low; int high; bool visited; };
    std::stack<Frame> st;
    std::stack<string> res;
    st.push({low, high, false});

    while(!st.empty()) {
        Frame f = st.top(); st.pop();
        int l = f.low;
        int h = f.high;
        if(l == h) {
            res.push(arr[l]);
        } else if(!f.visited) {
            f.visited = true;
            st.push(f);
            int mid = l + (h - l) / 2;
            st.push({mid + 1, h, false});
            st.push({l, mid, false});
        } else {
            string right = res.top(); res.pop();
            string left  = res.top(); res.pop();
            res.push(commonPrefixUtil(left, right));
        }
    }
    return res.top();
}

