int lps(char* seq,int i,int j) {
    if (i > j) return 0;
    if (i == j) return 1;

    struct Node { int i; int j; };
    stack<Node> st;
    st.push({i,j});

    map<pair<int,int>,int> memo;

    while (!st.empty()) {
        Node cur = st.top();
        st.pop();
        int ci = cur.i;
        int cj = cur.j;
        if (ci > cj) { memo[{ci,cj}] = 0; continue; }
        if (memo.find({ci,cj}) != memo.end()) continue;
        if (ci == cj) { memo[{ci,cj}] = 1; continue; }
        if (seq[ci] == seq[cj] && ci + 1 == cj) { memo[{ci,cj}] = 2; continue; }

        if (seq[ci] == seq[cj]) {
            pair<int,int> child = {ci+1, cj-1};
            if (memo.find(child) == memo.end()) {
                st.push({ci,cj});
                st.push({child.first, child.second});
            } else {
                memo[{ci,cj}] = memo[child] + 2;
            }
        } else {
            pair<int,int> left  = {ci, cj-1};
            pair<int,int> right = {ci+1, cj};
            bool leftDone  = memo.find(left)  != memo.end();
            bool rightDone = memo.find(right) != memo.end();
            if (!leftDone || !rightDone) {
                st.push({ci,cj});
                if (!rightDone) st.push({right.first, right.second});
                if (!leftDone)  st.push({left.first,  left.second});
            } else {
                memo[{ci,cj}] = max(memo[left], memo[right]);
            }
        }
    }
    return memo[{i,j}];
}

