    vector<vector<vector<int>>> dp(n + 1, vector<vector<int>>(n + 1, vector<int>(2, -1)));

    // Lambda for bottom-up / memoized DP to avoid recursion overhead and manage state cleanly
    auto solve = [&](auto& self, int idx, int p, int m) -> int {
        if (idx >= n) {
            return 0;
        }
        if (dp[idx][p + 1][m] != -1) {
            return dp[idx][p + 1][m];
        }

        int take = 0;
        int skip = 0;

        if (p == -1 || (nums[p] + nums[idx]) % 2 == m) {
            take = 1 + self(self, idx + 1, idx, m);
        }
        skip = self(self, idx + 1, p, m);

        return dp[idx][p + 1][m] = max(take, skip);
    };

    return solve(solve, i, prev, mod);
