#include <vector>
#include <cmath>

int solve(int n, int p) {
    // This problem exhibits overlapping subproblems (similar to 0/1 knapsack / subset sum).
    // We use memoization via a 2D DP table. 
    // Since 'p' starts at 0 and increments, p cannot exceed a reasonable bound (approx log3(n) + buffer).
    // We size the table dynamically based on 'n' and a safe upper bound for 'p'.

    // Calculate maximum possible p needed
    int max_p = 0;
    long long pow3 = 1;
    while (pow3 <= n) {
        pow3 *= 3;
        max_p++;
    }
    max_p += 2; // safety margin

    // memo table initialized to -1 (unvisited), 0 (false), 1 (true)
    // dimensions: (n + 1) x max_p
    std::vector<std::vector<int>> memo(n + 1, std::vector<int>(max_p, -1));

    auto dp = [&](auto& self, int current_n, int current_p) -> bool {
        if (current_n == 0) {
            return true;
        }

        // Compute 3^current_p safely
        long long current_pow = 1;
        for (int i = 0; i < current_p; ++i) {
            current_pow *= 3;
            if (current_pow > current_n) break;
        }

        if (current_pow > current_n) {
            return false;
        }

        if (current_p >= max_p) {
            return false;
        }

        if (memo[current_n][current_p] != -1) {
            return memo[current_n][current_p] == 1;
        }

        bool p_ko_lelo = self(self, current_n - current_pow, current_p + 1);
