bool isMatch(std::string text, std::string pattern) {
    int m = text.length();
    int n = pattern.length();

    // dp[i][j] represents whether text[i:] matches pattern[j:]
    std::vector<std::vector<int>> memo(m + 1, std::vector<int>(n + 1, -1));

    auto dp = [&](auto& self, int i, int j) -> bool {
        if (j == n) {
            return i == m;
        }
        if (memo[i][j] != -1) {
            return memo[i][j];
        }

        bool first_char_matched = (i < m && (pattern[j] == text[i] || pattern[j] == '.'));

        bool ans = false;
        if (j + 1 < n && pattern[j + 1] == '*') {
            ans = self(self, i, j + 2) || (first_char_matched && self(self, i + 1, j));
        } else {
            ans = first_char_matched && self(self, i + 1, j + 1);
        }

        return memo[i][j] = ans;
    };

    return dp(dp, 0, 0);
}

