#include <cmath>

int numberOfWays(int n, int k) {
    // Create a DP table with dimensions (n + 1) x (k + 1), initialized to -1
    vector<vector<long long>> dp(n + 1, vector<long long>(k + 1, -1));

    // Lambda for memoized recursive computation
    auto solve = [&](auto& self, int curr_n, int curr_k) -> long long {
        if (curr_n == 0) return 1;
        if (curr_k == 0) return 1;
        if (dp[curr_n][curr_k] != -1) return dp[curr_n][curr_k];

        // Compute powers safely or handle condition
        // Note: pow(2, curr_k) can grow fast, but we match the original logic bounds
        double p = std::pow(2.0, curr_k);
        if (curr_n >= p) {
            int curr_val = static_cast<int>(p);
            dp[curr_n][curr_k] = self(self, curr_n - curr_val, curr_k) + self(self, curr_n, curr_k - 1);
        } else {
            dp[curr_n][curr_k] = self(self, curr_n, curr_k - 1);
        }
        return dp[curr_n][curr_k];
    };

    return static_cast<int>(solve(solve, n, k));
}

