#include <cmath>

int countSeq(int n, int diff) {
    if (abs(diff) > n) return 0;

    // diff can range from -n to n, total 2*n + 1 possible values.
    // We shift diff by +n to map it to the range [0, 2*n].
    // Since states at step i depend on step i-1, we can use a rolling 2D DP table
    // or a full DP table of size (n + 1) x (2 * n + 1).

    int offset = n;
    int width = 2 * n + 1;

    // dp[i][d] stores countSeq(i, d - offset)
    vector<vector<long long>> dp(n + 1, vector<long long>(width, 0));

    // Base case for n = 1
    if (1 <= n) {
        if (abs(0) <= 1) dp[1][0 + offset] = 2;
        if (abs(1) <= 1) dp[1][1 + offset] = 1;
        if (abs(-1) <= 1) dp[1][-1 + offset] = 1;
    }

    for (int i = 2; i <= n; ++i) {
        for (int d = -i; d <= i; ++d) {
            if (abs(d) > i) continue;
            long long val1 = (abs(d + 1) <= i - 1) ? dp[i - 1][d + 1 + offset] : 0;
            long long val2 = (abs(d) <= i - 1) ? dp[i - 1][d + offset] : 0;
            long long val3 = (abs(d - 1) <= i - 1) ? dp[i - 1][d - 1 + offset] : 0;

            dp[i][d + offset] = val1 + 2 * val2 + val3;
        }
    }

    return dp[n][diff + offset];
}

