const int INF = 1e7;

int min_op(int cur, int M) {
    if (cur > M) return INF;
    if (cur == M) return 0;

    // Using a dynamic programming / memoization table sized by M+1
    vector<int> dp(M + 1, INF);
    dp[M] = 0;

    for (int current = M - 1; current >= cur; --current) {
        int op = INF;
        for (int i = 2; i * i <= current; ++i) {
            if (current % i == 0) {
                if (i % 2 == 0) {
                    if (current + i <= M) {
                        op = min(op, 1 + dp[current + i]);
                    } else {
                        op = min(op, 1 + INF);
                    }
                }
                int d = current / i;
                if (d != i && d % 2 == 0) {
                    if (current + d <= M) {
                        op = min(op, 1 + dp[current + d]);
                    } else {
                        op = min(op, 1 + INF);
                    }
                }
            }
        }
        dp[current] = op;
    }

    return dp[cur];
}

