int maxProd(int N) {
    if (N == 0) return 1;
    if (N < 10) return N;

    // The recursive states depend on N / 10 and (N / 10) - 1.
    // Since the state space is not trivially bounded by a small continuous array
    // due to the division, we can use a memoization map (or hash table) 
    // to avoid recomputing overlapping subproblems.
    // However, to keep standard container usage minimal and efficient:
    static int memo[1000000]; // Alternatively use std::unordered_map for arbitrary N

    // For a safe, general memoisation approach with arbitrary N:
    // Since no fixed constant sizing is allowed unless derived from arguments, 
    // we can use a helper lambda with std::unordered_map.

    unordered_map<int, int> memo_map;

    auto dp = [&](auto& self, int n) -> int {
        if (n == 0) return 1;
        if (n < 10) return n;
        if (memo_map.count(n)) return memo_map[n];

        int res = max(self(self, n / 10) * (n % 10), self(self, n / 10 - 1) * 9);
        return memo_map[n] = res;
    };

    return dp(dp, N);
}

