int countSortedArrays(int start, int m, int size, int n) {
    // Dimensions for DP table:
    // size ranges from 0 to m (size + 1 states)
    // start ranges from 1 to n + 1 (n + 2 states)
    int sizeRows = m + 1;
    int startCols = n + 2;

    vector<vector<int>> dp(sizeRows, vector<int>(startCols, 0));

    // Base cases:
    // When size == m, return 1 for all valid start <= n + 1
    for (int s = 1; s <= n + 1; ++s) {
        dp[m][s] = 1;
    }

    // Fill the table bottom-up
    for (int sz = m - 1; sz >= 0; --sz) {
        for (int st = n + 1; st >= 1; --st) {
            int taken = 0;
            int notTaken = 0;

            // taken: countSortedArrays(start, m, size + 1, n)
            if (sz + 1 <= m) {
                taken = dp[sz + 1][st];
            }

            // notTaken: countSortedArrays(start + 1, m, size, n)
            if (st + 1 <= n + 1) {
                notTaken = dp[sz][st + 1];
            } else {
                // When start > n, base case returns 0
                notTaken = 0;
            }

            dp[sz][st] = taken + notTaken;
        }
    }

    // If initial start exceeds n, return 0 based on base case
    if (start > n) return 0;

    return dp[size][start];
}

