int dfs(const vector<int>& v, const vector<int>& lens, int index, int cur) {
    // Using a memoization map since state is defined by (index, cur)
    // Key can be packed as index << 20 | cur (assuming cur fits within 20 bits, or use a pair/custom hash)
    // To be safe and generic with the exact signature, we use a static or local memo structure.
    // Since index ranges up to v.size() and cur can vary, a hash map is robust.
    // Note: To keep thread-safety or avoid static state issues across calls, we can use a helper with a map.

    struct Memo {
        // key: index * max_cur + cur, or a nested map / hash_map
        // Given standard competitive programming constraints, a 2D memo table or hash map works.
    };

    // Using a lambda with a capture for memoization:
    static auto memo_dfs = [](auto& self, const vector<int>& v, const vector<int>& lens, int index, int cur, auto& memo) -> int {
        if (index == v.size()) return 0;

        long long key = ((long long)index << 32) | cur;
        if (memo.count(key)) return memo[key];

        int res = self(self, v, lens, index + 1, cur, memo);

        if (!(cur & v[index])) {
            res = max(res, lens[index] + self(self, v, lens, index + 1, cur | v[index], memo));
        }

        return memo[key] = res;
    };

