            return dp[i][j];

        if (i > j) 
            return dp[i][j] = self(self, i - 1, j) + self(self, i - 2, j);
        else if (j == i) 
            return dp[i][j] = self(self, i - 1, j - 1) + self(self, i - 2, j - 2);

        return dp[i][j] = 0;
    };

    return solve(solve, n, m);
}

