int countNumbersWith4(int n) {
    if (n < 4) return 0;
    int d = log10(n);

    // Size the table dynamically from the arguments
    vector<int> a(d + 1);
    if (d >= 0) a[0] = 0;
    if (d >= 1) a[1] = 1;
    for (int i = 2; i <= d; ++i) {
        a[i] = a[i - 1] * 9 + ceil(pow(10, i - 1));
    }

    int current_n = n;
    int total_count = 0;

    // Iterative approach to avoid recursive overlapping subproblem recomputations
    while (current_n >= 4) {
        int current_d = log10(current_n);
        int p = ceil(pow(10, current_d));
        int msd = current_n / p;

        if (msd == 4) {
            total_count += msd * a[current_d] + (current_n % p) + 1;
            break;
        } else if (msd > 4) {
