int LIS(vector<int>& nums, int i, int prev, int mod) {
    int n = nums.size();
    // Memoization table of size (n + 1) x (n + 1)
    // prev ranges from -1 to n-1, so we offset it by +1 (mapping -1 to 0, 0 to 1, ..., n-1 to n)
    // i ranges from 0 to n
    vector<vector<int>> memo(n + 1, vector<int>(n + 1, -1));

    auto dp = [&](auto& self, int idx, int p) -> int {
        if (idx >= n) {
            return 0;
        }

        int p_offset = p + 1;
        if (memo[idx][p_offset] != -1) {
            return memo[idx][p_offset];
        }

        int take = 0;
        int skip = 0;

        // take
        if (p == -1 || (nums[p] + nums[idx]) % 2 == mod) {
            take = 1 + self(self, idx + 1, idx);
