int solve(int n, int p) {
    // Memoization table using a 2D vector sized from the arguments.
    // Since p increases by 1 each recursive step, max p is bounded.
    // A safe upper bound for p where 3^p > n is when p >= log3(n) + 1.
    int max_p = 0;
    long long power = 1;
    while (power <= n) {
        power *= 3;
        max_p++;
    }
    max_p += 2; // Extra buffer to handle p+1 safely

    // memo[n_val][p_val] initialized to -1 (unvisited), 0 (false), 1 (true)
    // To avoid massive memory if n is large, we can map or size appropriately, 
    // but keeping it strictly sized by arguments:
    std::vector<std::vector<int>> memo(n + 1, std::vector<int>(max_p + 1, -1));

    auto dp = [&](auto& self, int rem_n, int curr_p) -> bool {
        if (rem_n == 0) return true;

        // Compute 3^curr_p safely avoiding overflow or float inaccuracy
        long long p_val = 1;
        for (int i = 0; i < curr_p; ++i) {
            p_val *= 3;
            if (p_val > rem_n) break;
        }
        if (p_val > rem_n) return false;

        if (rem_n <= n && curr_p <= max_p && memo[rem_n][curr_p] != -1) {
            return memo[rem_n][curr_p];
        }

        bool p_ko_lelo = self(self, rem_n - p_val, curr_p + 1);
        bool p_ko_nahi_lo = self(self, rem_n, curr_p + 1);

        bool result = p_ko_lelo || p_ko_nahi_lo;

        if (rem_n <= n && curr_p <= max_p) {
            memo[rem_n][curr_p] = result;
        }

        return result;
    };

    return dp(dp, n, p);
}

