using namespace std;

int intCount(int X, int K) {
    int ans = 0;
    // Using an explicit stack to replace implicit recursion / control flow if needed,
    // or managing the loop states explicitly. Here, the original code uses a simple loop,
    // but we can structure it with a stack to meet the architectural requirement.
    struct State {
        int z;
        int step;
    };

    double pow10K = pow(10, K);
    int step = (pow10K - 1) / 9;

    std::stack<int> s;
    // Push the initial starting point of z
    s.push(0);

    while (!s.empty()) {
        int z = s.top();
        s.pop();

        if (z > X) continue;

        ans += ((X - z) / pow10K + 1);

        // Instead of next loop iteration, push the next state
        int next_z = z + step;
        if (next_z < pow10K) {
            s.push(next_z);
        }
    }
    return ans;
}

int intCountInRange(int L, int R, int K) {
    return (intCount(R, K) - intCount(L - 1, K));
