char findKthChar(string s, int k) {
    struct State {
        string s;
        int k;
    };

    std::stack<State> callStack;
    callStack.push({s, k});

    char result = -1;
    bool hasResult = false;

    while (!callStack.empty() && !hasResult) {
        State current = callStack.top();
        callStack.pop();

        string current_s = current.s;
        int current_k = current.k;

        int len = current_s.length();
        int i = 0;
        int total_len = 0;

        while (i < len) {
            if (isalpha(current_s[i])) {
                total_len++;
                if (total_len == current_k) {
                    result = current_s[i];
                    hasResult = true;
                    break;
                }
                i++;
            } else {
                int n = 0;
                while (i < len && !isalpha(current_s[i])) {
                    n = n * 10 + (current_s[i] - '0');
                    i++;
                }
                int next_total_len = total_len * n;
                if (current_k <= next_total_len) {
                    int pos = current_k % total_len;
                    if (!pos) {
                        pos = total_len;
                    }
                    callStack.push({current_s, pos});
                    break;
                } else {
                    total_len = next_total_len;
                }
            }
        }
