#include <iostream>
#include <stack>

int usingBinarySearch(int start, int end, int N, int S) {
    struct Range {
        int start;
        int end;
    };

    std::stack<Range> st;
    st.push({start, end});

    int last_start = start;
    int last_end = end;

    while (!st.empty()) {
        Range current = st.top();
        st.pop();

        if (current.start >= current.end) {
            last_start = current.start;
            continue;
        }

        int mid = current.start + (current.end - current.start) / 2;
        long long totalSum = (static_cast<long long>(N) * (N + 1)) / 2;
        long long midSum = (static_cast<long long>(mid) * (mid + 1)) / 2;

        if ((totalSum - midSum) <= S) {
            st.push({current.start, mid});
        } else {
            st.push({mid + 1, current.end});
        }
    }

    return last_start;
}

