#include <stack>

using namespace std;

int fact(int n) {
    if (n <= 1) return 1;
    int result = 1;
    stack<int> s;
    s.push(n);
    while (!s.empty()) {
        int current = s.top();
        s.pop();
        result *= current;
        if (current - 1 > 1) {
            s.push(current - 1);
        }
    }
    return result;
}

int nPr(int n, int r) {
    return fact(n) / fact(n - r);
}

int countWords(int N, int M) {
    return pow(N, M) - nPr(N, M);
}
